class Counter:
    def __init__(self, stop):
        self.current = 1
        self.stop = stop
    def __iter__(self):
        return self
    def __next__(self):
        if self.current > self.stop:
            raise StopIteration
        value = self.current
        self.current += 1
        return value
print(list(Counter(3)))

class Evens:
    def __init__(self, count):
        self.value = 0
        self.count = count
    def __iter__(self):
        return self
    def __next__(self):
        if self.count == 0:
            raise StopIteration
        result = self.value
        self.value += 2
        self.count -= 1
        return result
print(list(Evens(4)))

class Steps:
    def __init__(self):
        self.values = ['start', 'middle', 'end']
        self.index = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self.index >= len(self.values):
            raise StopIteration
        item = self.values[self.index]
        self.index += 1
        return item
it = Steps()
print(next(it))
print(next(it))

class Countdown:
    def __init__(self, start):
        self.value = start
    def __iter__(self):
        return self
    def __next__(self):
        if self.value < 1:
            raise StopIteration
        result = self.value
        self.value -= 1
        return result
for n in Countdown(3):
    print(n)

class RangeBox:
    def __init__(self, stop):
        self.stop = stop
    def __iter__(self):
        return iter(range(self.stop))
box = RangeBox(2)
print(list(box))
